let db; let currentUser=null,revision=0, ready=false, busy=false;
const accept=value=>{db=value.data;revision=value.revision;};
async function loadRemote(){const [r,a]=await Promise.all([fetch('/api/state',{cache:'no-store'}),fetch('/api/auth/me',{cache:'no-store'})]);if(!r.ok)throw new Error('โหลดข้อมูลไม่สำเร็จ');accept(await r.json());currentUser=a.ok?(await a.json()).user:null;}
async function save(){const r=await fetch('/api/state',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({data:db,revision})});const result=await r.json();if(!r.ok)throw new Error(result.error||'บันทึกไม่สำเร็จ');accept(result);}
function guarded(handler){return async e=>{if(!ready||busy){if(e.type==='submit')e.preventDefault();return}busy=true;try{await handler(e)}catch(err){try{await loadRemote();render()}catch{}toast(err.message||'ทำรายการไม่สำเร็จ')}finally{busy=false}}}
async function authRequest(mode,data){const r=await fetch('/api/auth/'+mode,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}),result=await r.json();if(!r.ok)throw new Error(result.error);currentUser=result.user;}
function updateHeader(){const a=$('#auth-link');if(!a)return;a.href=currentUser?'#lookup':'#login';a.innerHTML=currentUser?`${esc(currentUser.firstName)} · ตั๋วของฉัน <span>↗</span>`:'เข้าสู่ระบบ <span>↗</span>';}
