const closeDialog=()=>$('#dialog').close();
function poster(m,wide=false){if(FILMS[m.id])return `<img class="real-poster ${wide?'wide-poster':'standard-poster'}" src="${FILMS[m.id].posterUrl||'assets/'+FILMS[m.id].art+'.jpg'}" alt="โปสเตอร์ ${esc(m.name)}" ${wide?'fetchpriority="high"':'loading="lazy"'}>`;const uid='art-'+m.id+(wide?'-wide':'');const palettes={horizon:['#172b2c','#4b6d62','#eab37c'],kyoto:['#583841','#b57069','#f3ca9e'],orbit:['#11172e','#5360a7','#bdbbef'],forest:['#24553c','#8fba76','#f5e8a6'],rain:['#3d6465','#8fb2a0','#e8d8a2'],echo:['#2e2935','#74606c','#d6b58f']};const p=palettes[m.art]||palettes.horizon;const view=wide?'0 0 600 420':'0 0 300 400';const art=m.art==='orbit'?`<circle cx="180" cy="145" r="75" fill="url(#${uid}sun)"/><ellipse cx="180" cy="145" rx="128" ry="20" transform="rotate(-25 180 145)" fill="none" stroke="#d3c5f0" stroke-width="10" opacity=".6"/><path d="M123 307l7-31 8 31z" fill="white"/><path d="M129 312v24" stroke="#ffcba6" stroke-width="3"/>`:m.art==='kyoto'?`<circle cx="150" cy="100" r="52" fill="${p[2]}" opacity=".8"/><path d="M15 227h270L235 205h-35v-35h-100v35H65zM48 252h200l-30-21H78z" fill="#342b38"/><path d="M82 245v90m136-90v90M102 273h98" stroke="#342b38" stroke-width="13"/><path d="M50 342Q150 305 250 342" fill="none" stroke="#d5b89a" stroke-width="3"/>`:m.art==='forest'?`<circle cx="220" cy="80" r="42" fill="${p[2]}"/><path d="M0 230Q80 120 170 215Q240 160 300 210v190H0z" fill="#315d3e"/><path d="M0 280Q120 190 300 300v100H0z" fill="#73976a"/><path d="M20 245L58 112l40 133M210 228l32-118 39 118" fill="#244e37"/><ellipse cx="134" cy="278" rx="25" ry="32" fill="#f0d397"/><circle cx="126" cy="269" r="3" fill="#344230"/><circle cx="143" cy="269" r="3" fill="#344230"/><ellipse cx="191" cy="291" rx="17" ry="22" fill="#adbea2"/>`:m.art==='rain'?`<circle cx="214" cy="87" r="43" fill="${p[2]}" opacity=".8"/><path d="M35 245V162h225v150H35" fill="#335a55"/><path d="M30 160h235l-32-37H62z" fill="#183f3e"/><path d="M60 195h55v85H60zM150 195h80v55h-80z" fill="#c8d0a9"/><path d="M40 317h220" stroke="#d6cd99" stroke-width="4"/><path d="M20 180v27m48-138v27m60-13v27m155 54v27m-25-130v27" stroke="#d6e6da" stroke-width="2"/>`:m.art==='echo'?`<path d="M46 325V147L150 92l103 55v178z" fill="#29252f"/><path d="M112 326V179h77v147" fill="#9b7980"/><path d="M130 325V193h42v132" fill="#f0c89e" opacity=".75"/><path d="M50 340Q150 283 253 340" stroke="#a28786" stroke-width="2" fill="none"/>`:`<circle cx="225" cy="90" r="42" fill="${p[2]}" opacity=".8"/><path d="M0 275L78 146l61 93 74-114 87 142v133H0z" fill="#36544f"/><path d="M0 306l90-103 77 68 59-71 74 113v87H0z" fill="#173d38"/><path d="M145 400l-4-102 23-63 11 55-3 110" fill="#91a88c" opacity=".4"/><path d="M116 297l10-25 10 25z" fill="#ed9b62"/><path d="M126 295v17" stroke="#ed9b62" stroke-width="4"/>`;
return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="${view}" role="img" aria-label="โปสเตอร์ ${esc(m.name)}"><defs><linearGradient id="${uid}" x2="0" y2="1"><stop stop-color="${p[0]}"/><stop offset="1" stop-color="${p[1]}"/></linearGradient><radialGradient id="${uid}sun"><stop stop-color="${p[2]}"/><stop offset="1" stop-color="${p[1]}"/></radialGradient></defs><rect width="600" height="450" fill="url(#${uid})"/>${wide?'<g transform="translate(90,-40) scale(1.5)">':''}${Array.from({length:16},(_,i)=>`<circle cx="${(i*67+21)%300}" cy="${(i*37+20)%200}" r="${i%3===0?1.4:.7}" fill="#ffffff" opacity=".4"/>`).join('')}${art}${wide?'</g>':`<rect y="320" width="300" height="80" fill="${p[0]}" opacity=".82"/><text x="150" y="351" fill="#f5eada" text-anchor="middle" font-family="Georgia,serif" font-size="${m.name.length>18?16:20}" letter-spacing="2">${esc(m.name.toUpperCase())}</text><text x="150" y="376" fill="#dbddc9" text-anchor="middle" font-family="Arial,sans-serif" font-size="8" letter-spacing="3">A CINEMA67 ORIGINAL</text>`}</svg>`}
function qr(text){let hash=2166136261;for(const c of text)hash=Math.imul(hash^c.charCodeAt(0),16777619)>>>0;let cells='';const finder=(x,y)=>x<7&&y<7||x>=18&&y<7||x<7&&y>=18;for(let y=0;y<25;y++)for(let x=0;x<25;x++){if(finder(x,y)){let xx=x>=18?x-18:x, yy=y>=18?y-18:y;if(xx===0||xx===6||yy===0||yy===6||xx>=2&&xx<=4&&yy>=2&&yy<=4)cells+=`<rect x="${x}" y="${y}" width="1" height="1"/>`;}else if(!((x===7||x===17)&&y<8||y===7&&(x<8||x>16)||x===7&&y>16||y===17&&x<8)){hash=(Math.imul(hash,1664525)+1013904223)>>>0;if(hash%3!==0)cells+=`<rect x="${x}" y="${y}" width="1" height="1"/>`;}}return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="-2 -2 29 29" role="img" aria-label="QR จำลองสำหรับ Demo"><rect x="-2" y="-2" width="29" height="29" fill="white"/><g fill="#202722">${cells}</g></svg>`}
const movieCard=m=>`<article class="movie-card"><div class="poster">${poster(m)}<span class="poster-label">${m.upcoming?'เร็ว ๆ นี้':m.type==='IMAX'?'IMAX · NOW SHOWING':'NOW SHOWING'}</span><span class="poster-tag">${m.rating}</span></div><h3>${esc(m.name)}</h3><p class="movie-meta">${esc(m.genre)} <span>·</span> ${m.duration} นาที</p><button class="card-book" data-action="book" data-id="${m.id}" ${m.upcoming?'disabled':''}>${m.upcoming?'พบกันเร็ว ๆ นี้':'เลือกรอบฉาย'}<span>↗</span></button></article>`;
function home(){return `<section class="hero"><div class="hero-copy"><div class="eyebrow">MAKE TIME FOR A GOOD MOVIE</div><h1>วันธรรมดา<br>ให้หนังดี ๆ <span>เติมเต็ม</span></h1><p>เลือกหนัง เลือกที่นั่ง แล้วไปสนุกกัน<br>${currentUser?'พร้อมจองในชื่อ '+esc(currentUser.firstName):'เข้าสู่ระบบครั้งเดียว ข้อมูลไม่ซ้ำ'}</p><button class="button" data-action="scroll-movies">เลือกหนังที่อยากดู <span>↗</span></button><div class="hero-foot"><span>◉ จองง่ายในไม่กี่ขั้นตอน</span><span>◈ รับตั๋วทันที</span></div></div><div class="hero-art">${poster(movie('m1'),true)}<div class="feature"><div><div class="eyebrow">FEATURED THIS WEEK</div><h2>DUNE<br>PART TWO</h2><p>ผจญภัย · 167 นาที · IMAX</p></div><button class="circle-button" data-action="book" data-id="m1" aria-label="จอง Dune: Part Two">↗</button></div></div></section>${recommended()}<section id="movies"><div class="section-head"><div><h2>เรื่องไหนที่ใช่คุณ</h2><p>ให้เวลาพักของคุณเป็นช่วงเวลาดี ๆ</p></div><div class="tabs"><button data-action="movie-tab" data-id="now" class="${movieTab==='now'?'active':''}">กำลังฉาย</button><button data-action="movie-tab" data-id="soon" class="${movieTab==='soon'?'active':''}">เร็ว ๆ นี้</button></div></div><div class="filter-bar"><div class="search-field"><span>⌕</span><label class="sr-only" for="movie-search">ค้นหาภาพยนตร์</label><input id="movie-search" placeholder="ค้นหาหนังที่อยากดู" value="${esc(search)}"></div><label class="sr-only" for="genre-filter">ประเภทหนัง</label><select id="genre-filter"><option value="">ทุกประเภท</option>${[...new Set(db.movies.map(x=>x.genre))].map(x=>`<option ${genre===x?'selected':''}>${esc(x)}</option>`).join('')}</select></div><div class="movie-grid" id="movie-results">${movieResults()}</div></section><div class="promo-strip"><span class="promo-icon">✳</span><div><h3>ดูหนังให้คุ้มขึ้นอีกนิด</h3><p>ใช้โค้ด MOVIE10 ลด 10% เมื่อครบ 300 บาท</p></div><a href="#promotions">ดูโปรโมชั่น <span>↗</span></a></div>`}
function movieResults(){const list=db.movies.filter(m=>m.active&&(m.id!=='m7'||search||genre)&&m.upcoming===(movieTab==='soon')&&(!genre||m.genre===genre)&&`${m.name} ${m.thai}`.toLowerCase().includes(search.toLowerCase()));return list.length?list.map(movieCard).join(''):'<div class="empty"><strong>ยังไม่พบหนังที่ค้นหา</strong>ลองเปลี่ยนชื่อหรือประเภทหนัง</div>'}
let recommendedIndex=0,recommendedPaused=false,recommendedTimer;
const recommendedMovies=()=>['m7','m11','m3','m14','m12'].map(movie).filter(m=>m?.active&&!m.upcoming);
function recommended(){const picks=recommendedMovies();if(!picks.length)return '';recommendedIndex%=picks.length;return `<section class="recommend-carousel" aria-label="ภาพยนตร์แนะนำ" aria-roledescription="carousel"><div class="recommend-slides">${picks.map((m,i)=>`<article class="recommended recommend-slide ${i===recommendedIndex?'is-active':''}" data-slide="${i}" aria-label="${i+1} จาก ${picks.length}: ${esc(m.name)}" aria-roledescription="slide" aria-hidden="${i!==recommendedIndex}" ${i===recommendedIndex?'':'inert'}><div class="recommended-poster">${poster(m)}</div><div class="recommended-copy"><div class="eyebrow">หนังแนะนำ</div><h2>${esc(m.name)}</h2><p class="muted">${esc(m.description)}</p><div class="recommended-meta"><span>${esc(m.genre)}</span><span>${m.duration} นาที</span><span>${esc(m.language||'เสียงไทย')}</span></div><div class="recommended-actions"><button class="button" data-action="book" data-id="${m.id}">จองเรื่องนี้ →</button>${m.id==='m7'?'<a class="text-button" href="https://www.youtube.com/watch?v=2nCAM-dtXqw" target="_blank" rel="noopener noreferrer">ดูตัวอย่าง ↗</a>':''}</div></div><div class="recommended-decoration" aria-hidden="true">67<span>STAFF PICK</span></div></article>`).join('')}</div><div class="recommend-controls"><div class="recommend-dots">${picks.map((m,i)=>`<button class="recommend-dot ${i===recommendedIndex?'is-active':''}" data-recommend-index="${i}" aria-label="ดูหนังแนะนำ: ${esc(m.name)}" aria-pressed="${i===recommendedIndex}"></button>`).join('')}</div><div class="recommend-navigation"><span class="recommend-count">${recommendedIndex+1} / ${picks.length}</span><button class="icon-button" data-recommend="prev" aria-label="หนังแนะนำก่อนหน้า">←</button><button class="icon-button" data-recommend="pause" aria-label="${recommendedPaused?'เล่นสไลด์อัตโนมัติ':'หยุดสไลด์อัตโนมัติ'}" aria-pressed="${recommendedPaused}">${recommendedPaused?'▶':'Ⅱ'}</button><button class="icon-button" data-recommend="next" aria-label="หนังแนะนำถัดไป">→</button></div></div></section>`}
function moveRecommended(index){const root=$('.recommend-carousel');if(!root)return;const slides=$$('[data-slide]',root);recommendedIndex=(index+slides.length)%slides.length;slides.forEach((slide,i)=>{const active=i===recommendedIndex;slide.classList.toggle('is-active',active);slide.setAttribute('aria-hidden',String(!active));slide.inert=!active;});$$('[data-recommend-index]',root).forEach((dot,i)=>{dot.classList.toggle('is-active',i===recommendedIndex);dot.setAttribute('aria-pressed',String(i===recommendedIndex))});$('.recommend-count',root).textContent=(recommendedIndex+1)+' / '+slides.length;}
function scheduleRecommended(){clearTimeout(recommendedTimer);recommendedTimer=setTimeout(()=>{const root=$('.recommend-carousel');if(root&&!recommendedPaused&&!document.hidden&&!root.matches(':hover')&&!root.contains(document.activeElement)&&!matchMedia('(prefers-reduced-motion: reduce)').matches)moveRecommended(recommendedIndex+1);scheduleRecommended()},5000)}
document.addEventListener('click',e=>{const el=e.target.closest('[data-recommend],[data-recommend-index]');if(!el)return;if(el.dataset.recommend==='pause'){recommendedPaused=!recommendedPaused;el.setAttribute('aria-pressed',String(recommendedPaused));el.setAttribute('aria-label',recommendedPaused?'เล่นสไลด์อัตโนมัติ':'หยุดสไลด์อัตโนมัติ');el.textContent=recommendedPaused?'▶':'Ⅱ';}else moveRecommended(el.dataset.recommendIndex!==undefined?Number(el.dataset.recommendIndex):recommendedIndex+(el.dataset.recommend==='prev'?-1:1));scheduleRecommended()});
let recommendTouch;
document.addEventListener('touchstart',e=>{if(e.target.closest('.recommend-carousel'))recommendTouch={x:e.touches[0].clientX,y:e.touches[0].clientY};else recommendTouch=null},{passive:true});
document.addEventListener('touchend',e=>{if(!recommendTouch)return;const dx=e.changedTouches[0].clientX-recommendTouch.x,dy=e.changedTouches[0].clientY-recommendTouch.y;if(Math.abs(dx)>50&&Math.abs(dx)>Math.abs(dy)){moveRecommended(recommendedIndex+(dx<0?1:-1));scheduleRecommended()}recommendTouch=null},{passive:true});
scheduleRecommended();
function title(eye,name,sub='',right=''){return `<div class="page-title"><div><div class="eyebrow">${eye}</div><h1>${name}</h1>${sub?`<p>${sub}</p>`:''}</div>${right}</div>`}
function subtotal(b=booking){return b.seats.reduce((t,s)=>t+price(s),0)+Object.entries(b.items).reduce((t,[id,q])=>t+(product(id)?.price||0)*q,0)}
function updateDiscount(){const pr=db.promos.find(p=>p.active&&p.code===booking.promo);const sub=subtotal();booking.discount=pr&&sub>=pr.min?Math.min(sub,pr.kind==='percent'?Math.round(sub*pr.value/100):pr.value):0;}
function summary(){updateDiscount();const m=movie(booking.movie);return `<aside class="panel summary"><div class="summary-poster"><div class="mini-poster">${poster(m)}</div><div><h3>${esc(m.name)}</h3><div class="small muted">${m.duration} นาที · ${m.rating}</div></div></div><dl><dt>โรงภาพยนตร์</dt><dd>${esc(cinema(booking.cinema)?.name||'—')}</dd><dt>วันที่</dt><dd>${dateLabel(booking.date)}</dd><dt>รอบฉาย</dt><dd>${booking.time||'ยังไม่เลือก'}</dd><dt>ที่นั่ง</dt><dd>${booking.seats.join(', ')||'ยังไม่เลือก'}</dd></dl><div class="order-line"><span>ตั๋วภาพยนตร์</span><b>฿${money(booking.seats.reduce((t,s)=>t+price(s),0))}</b></div>${Object.entries(booking.items).filter(([,q])=>q>0).map(([id,q])=>`<div class="order-line"><span>${esc(product(id).name)} × ${q}</span><span>฿${money(product(id).price*q)}</span></div>`).join('')}${booking.discount?`<div class="order-line"><span>ส่วนลด ${esc(booking.promo)}</span><span style="color:var(--green)">−฿${money(booking.discount)}</span></div>`:''}<div class="total"><span>ยอดสุทธิ</span><strong>฿${money(subtotal()-booking.discount)}</strong></div><div class="small muted">ผู้จอง: ${esc(currentUser?.firstName||'กรุณาเข้าสู่ระบบ')}<br>ข้อมูลติดต่อจากบัญชีสมาชิก</div></aside>`}
function steps(){return `<ol class="steps">${['รอบฉาย','ที่นั่ง','อาหาร','ข้อมูลผู้จอง','ชำระเงิน'].map((x,i)=>`<li class="${i===booking.step?'active':i<booking.step?'done':''}"><b>${i<booking.step?'✓':i+1}</b><span>${x}</span></li>`).join('')}</ol>`}
function beginBooking(id){const m=movie(id);if(!m?.active||m.upcoming)return;if(!currentUser){sessionStorage.setItem('cinema67-return-movie',id);go('login');return}const c=db.cinemas.find(x=>x.active&&db.rooms.some(r=>r.cinema===x.id&&r.active&&r.movie===id));if(!c){toast('ยังไม่มีโรงภาพยนตร์ที่เปิดให้จอง');return}booking={movie:id,cinema:c.id,room:db.rooms.find(r=>r.cinema===c.id&&r.active&&r.movie===id).id,date:plusDate(1),time:'',seats:[],items:{},firstName:currentUser.firstName,lastName:currentUser.lastName,email:currentUser.email,phone:currentUser.phone,promo:'',discount:0,step:0};go('booking')}
const showKey=b=>`${b.movie}|${b.room}|${b.date}|${b.time}`;
function reserved(b=booking,exclude=''){let fixed=[];const h=[...showKey(b)].reduce((s,c)=>s+c.charCodeAt(0),0);if(h%2===0)fixed=['A3','A4','B6','D7'];else fixed=['B3','B4','C7','D1'];const records=db.bookings.filter(x=>x.id!==exclude&&showKey(x)===showKey(b)&&['paid','pending'].includes(x.status));return new Set([...fixed,...records.flatMap(x=>x.seats)])}
function bookingPage(){if(!movie(booking.movie))return home();let body='';if(booking.step===0){const m=movie(booking.movie);body=`<div class="detail-top"><div class="poster">${poster(m)}</div><div><span class="pill">${m.genre} · ${m.rating}</span><h2 style="margin-top:10px">${esc(m.name)}</h2><p>${esc(m.description)}</p><div class="small muted">${m.duration} นาที · ${esc(m.language)}</div></div></div><div class="form-grid"><div><label for="branch">โรงภาพยนตร์</label><select id="branch">${db.cinemas.filter(c=>c.active&&db.rooms.some(r=>r.cinema===c.id&&r.active&&r.movie===booking.movie)).map(c=>`<option value="${c.id}" ${c.id===booking.cinema?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><div><label for="room">ห้องฉาย</label><select id="room">${db.rooms.filter(r=>r.cinema===booking.cinema&&r.active&&r.movie===booking.movie).map(r=>`<option value="${r.id}" ${r.id===booking.room?'selected':''}>${esc(r.name)} · ${r.type}</option>`).join('')}</select></div></div><div class="dates">${Array.from({length:7},(_,i)=>{const d=plusDate(i);return `<button class="date-button ${d===booking.date?'active':''}" data-action="date" data-id="${d}"><span class="small">${new Date(d+'T12:00:00+07:00').toLocaleDateString('th-TH',{weekday:'short'})}</span><b>${Number(d.slice(-2))}</b><span class="small">${new Date(d+'T12:00:00+07:00').toLocaleDateString('th-TH',{month:'short'})}</span></button>`}).join('')}</div><label>รอบฉาย</label><div class="showtimes">${db.times.map(t=>`<button class="showtime ${booking.time===t?'active':''}" data-action="time" data-id="${t}" ${startTime({...booking,time:t})<=Date.now()?'disabled':''}><b>${t}</b><small>${esc(room(booking.room)?.type)} · ${esc(m.language)}</small></button>`).join('')}</div><div class="next-row"><span class="small muted">เลือกรอบที่สะดวก แล้วไปเลือกที่นั่ง</span><button class="button" data-action="next" ${!booking.time?'disabled':''}>เลือกที่นั่ง →</button></div>`;}
else if(booking.step===1){const taken=reserved();body=`<h2>ที่นั่งที่ถูกใจ</h2><p class="small muted">โซนปกติ ฿180 · โซนพิเศษ ฿250</p><div class="screen">SCREEN</div><div class="seat-map">${rows.map((r,i)=>`${i===4?'<div class="zone-label">PREMIUM · ฿250</div>':''}<span class="row-label">${r}</span>${Array.from({length:8},(_,j)=>{const s=r+(j+1);return `<button class="seat ${i>=4?'premium':''} ${booking.seats.includes(s)?'selected':''}" data-action="seat" data-id="${s}" ${taken.has(s)?'disabled':''} aria-label="ที่นั่ง ${s} ${taken.has(s)?'จองแล้ว':price(s)+' บาท'}" aria-pressed="${booking.seats.includes(s)}">${s}</button>`}).join('')}`).join('')}</div><div class="seat-legend"><span><i class="swatch"></i>ว่าง</span><span><i class="swatch selected"></i>เลือกแล้ว</span><span><i class="swatch taken"></i>จองแล้ว</span><span><i class="swatch premium"></i>พิเศษ</span></div><div class="seat-message">${booking.seats.length?`เลือก ${booking.seats.join(', ')} · ${booking.seats.length} ที่นั่ง`:'เลือกที่นั่งบนผังได้เลย'}</div><div class="next-row"><button class="button secondary" data-action="previous">← ย้อนกลับ</button><button class="button" data-action="next" ${!booking.seats.length?'disabled':''}>เลือกของทานเล่น →</button></div>`;}
else if(booking.step===2){body=`<h2>เติมความอร่อย</h2><p class="small muted">ซื้อไว้ แล้วรับหน้าโรงได้เลย</p><div class="product-grid">${db.products.filter(x=>x.active).map(p=>`<article class="product"><div class="product-art">${p.icon}</div><h3>${esc(p.name)}</h3><p>${esc(p.detail)} · ฿${money(p.price)}</p><div class="counter"><button data-action="quantity" data-id="${p.id}" data-delta="-1" aria-label="ลด ${esc(p.name)}" ${!booking.items[p.id]?'disabled':''}>−</button><span>${booking.items[p.id]||0}</span><button data-action="quantity" data-id="${p.id}" data-delta="1" aria-label="เพิ่ม ${esc(p.name)}">+</button></div></article>`).join('')}</div><div class="notice">หลังชำระเงิน จะได้รับคูปองสำหรับรับสินค้า</div><div class="next-row"><button class="button secondary" data-action="previous">← ย้อนกลับ</button><button class="button" data-action="next">${Object.values(booking.items).some(q=>q>0)?'ดำเนินการต่อ':'ข้ามขั้นตอนนี้'} →</button></div>`;}
else if(booking.step===3){body=`<h2>อีกนิดเดียวก็พร้อม</h2><p class="small muted">ข้อมูลผู้จองดึงจากบัญชีที่เข้าสู่ระบบ</p><form id="checkout-form"><div class="notice"><strong>${esc(currentUser.firstName)} ${esc(currentUser.lastName)}</strong><br>${esc(currentUser.email)} · ${esc(currentUser.phone)}</div><div class="field"><label for="promo">โค้ดส่วนลด</label><div class="inline-input"><input id="promo" placeholder="ลองใช้ MOVIE10" value="${esc(booking.promo)}"><button class="button secondary" type="button" data-action="apply-promo">ใช้โค้ด</button></div><div id="promo-message" class="small muted" style="margin-top:8px">${booking.discount?'ลดแล้ว ฿'+money(booking.discount):'MOVIE10 ลด 10% เมื่อครบ 300 บาท'}</div></div><div class="notice">กรุณาชำระภายใน 10 นาที หลังสร้างการจอง หากหมดเวลา ระบบจะคืนที่นั่งอัตโนมัติ</div><label class="check"><input type="checkbox" name="terms" required><span>ฉันตรวจสอบรอบฉาย ที่นั่ง และข้อมูลติดต่อแล้ว</span></label><div class="next-row"><button class="button secondary" type="button" data-action="previous">← ย้อนกลับ</button><button class="button" type="submit">ไปชำระเงิน →</button></div></form>`;}
return `<button class="back" data-action="leave-booking">← ภาพยนตร์ทั้งหมด</button>${steps()}<div class="booking-layout"><section class="panel">${body}</section>${summary()}</div>`;}
function paymentPage(id){const b=db.bookings.find(x=>x.id===id);if(!b)return notFound();booking={...b,step:4};if(b.status==='paid')return ticketPage(b);if(b.status!=='pending')return `${title('BOOKING CLOSED','รายการนี้สิ้นสุดแล้ว')}<div class="panel pay-panel"><h2>${b.status==='expired'?'หมดเวลาชำระเงิน':'การจองถูกยกเลิก'}</h2><p class="muted">คืนที่นั่งเรียบร้อยแล้ว สามารถเลือกจองใหม่ได้</p><button class="button" data-action="book" data-id="${b.movie}">จองใหม่ →</button></div>`;
return `${steps()}<div class="booking-layout"><section class="panel pay-panel"><span class="pill orange">รอชำระเงิน</span><h2>พร้อมสำหรับมื้อหนังดี ๆ</h2><p class="small muted">${b.id} · ฿${money(b.amount)}</p><div class="qr-wrap">${qr('pay:'+b.id)}</div><span class="small muted">QR จำลอง · ไม่สามารถใช้ชำระเงินจริง</span><div style="margin-top:18px"><span class="small muted">เวลาที่เหลือ</span><div class="countdown" id="countdown">${remaining(b)}</div></div><div class="notice">ใช้ปุ่มด้านล่างเพื่อสาธิตผลการชำระเงิน</div><button class="button full" data-action="pay-success" data-id="${id}">จำลองชำระเงินสำเร็จ ✓</button><div class="pay-controls"><button class="button secondary" data-action="pay-fail" data-id="${id}">ชำระไม่สำเร็จ</button><button class="button secondary" data-action="pay-expire" data-id="${id}">จำลองหมดเวลา</button><button class="text-button" data-action="cancel-pending" data-id="${id}">ยกเลิกรายการ</button></div><p id="pay-error" class="field-error" role="alert"></p></section>${summary()}</div>`;}
function remaining(b){const sec=Math.max(0,Math.ceil((b.deadline-Date.now())/1000));return `${String(Math.floor(sec/60)).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}`}
function ticketMarkup(b){const m=movie(b.movie);return `<article class="ticket"><div class="ticket-head"><h2>CINEMA67 <span style="color:#f5a48e">/ E-TICKET</span></h2>${badge(b.status)}</div><div class="ticket-body"><div><div class="eyebrow">YOUR NEXT GOOD MOMENT</div><h2 style="margin-top:12px">${esc(m?.name||b.movie)}</h2><p class="small muted">${esc(cinema(b.cinema)?.name)} · ${esc(room(b.room)?.name)}</p><dl><div><dt>วันที่</dt><dd>${dateLabel(b.date)}</dd></div><div><dt>รอบฉาย</dt><dd>${b.time} น.</dd></div><div><dt>ที่นั่ง</dt><dd>${b.seats.join(', ')}</dd></div><div><dt>ยอดชำระ</dt><dd>฿${money(b.amount)}</dd></div></dl></div><div class="qr-section">${b.status==='paid'?`<div class="qr-wrap">${qr(b.id)}</div><div class="small muted" style="text-align:center;margin-top:8px">QR จำลองสำหรับ Demo</div>`:'<div class="notice red">ตั๋วไม่สามารถใช้งานได้</div>'}</div></div><div class="ticket-bottom"><strong>${b.id}</strong><span>${esc(b.email)}</span></div></article>`}
function couponMarkup(b){const items=Object.entries(b.items).filter(([,q])=>q>0);if(!items.length||b.status!=='paid')return '';return `<div class="coupon"><div class="qr-wrap">${qr('food:'+b.id)}</div><div><h3>คูปองของทานเล่น ${b.couponUsed?'· ใช้แล้ว':''}</h3><p>${items.map(([id,q])=>`${esc(product(id)?.name)} × ${q}`).join(' · ')}</p><p>FOOD-${b.id} · QR จำลอง</p></div><span class="pill ${b.couponUsed?'grey':''}" style="margin-left:auto">${b.couponUsed?'ใช้แล้ว':'พร้อมรับ'}</span></div>`}
function ticketPage(b){return `<div class="success-head"><div class="success-mark">✓</div><div class="eyebrow" style="justify-content:center">YOU'RE ALL SET</div><h1>แล้วพบกันหน้าโรง</h1><p class="muted">บันทึกเลขการจองไว้ เพื่อค้นหาตั๋วครั้งถัดไป</p></div>${ticketMarkup(b)}${couponMarkup(b)}<div class="ticket-actions"><button class="button" data-action="download-ticket" data-id="${b.id}">ดาวน์โหลดตั๋ว ↓</button><button class="button secondary" data-action="email-preview" data-id="${b.id}">ตัวอย่างอีเมล</button><a class="button secondary" href="#home">กลับหน้าแรก</a></div><p class="small muted" style="text-align:center;margin-top:14px">ไม่มีการส่งอีเมลหรือเรียกเก็บเงินจริง</p>`}
function authPage(mode='login'){const register=mode==='register';return `${title('MEMBER ACCOUNT',register?'สมัครสมาชิก':'เข้าสู่ระบบ',register?'อีเมลและเบอร์โทรใช้ได้หนึ่งบัญชีเท่านั้น':'ใช้ข้อมูลบัญชีเพื่อจองและดูตั๋ว')}<div class="panel lookup-panel"><form id="auth-form" data-mode="${mode}">${register?`<div class="form-grid"><div class="field"><label for="auth-first">ชื่อ</label><input id="auth-first" name="firstName" maxlength="100" autocomplete="given-name" required></div><div class="field"><label for="auth-last">นามสกุล</label><input id="auth-last" name="lastName" maxlength="100" autocomplete="family-name" required></div></div>`:''}<div class="field"><label for="auth-email">อีเมล</label><input id="auth-email" name="email" type="email" autocomplete="email" required></div>${register?`<div class="field"><label for="auth-phone">เบอร์โทร</label><input id="auth-phone" name="phone" type="tel" pattern="0[0-9]{8,9}" maxlength="10" autocomplete="tel" required></div>`:''}<div class="field"><label for="auth-password">รหัสผ่าน</label><input id="auth-password" name="password" type="password" minlength="8" maxlength="128" autocomplete="${register?'new':'current'}-password" required></div><button class="button full">${register?'สร้างบัญชี':'เข้าสู่ระบบ'} →</button></form><p class="small muted" style="text-align:center;margin-top:18px">${register?'มีบัญชีแล้ว? <a href="#login">เข้าสู่ระบบ</a>':'ยังไม่มีบัญชี? <a href="#register">สมัครสมาชิก</a>'}</p><div class="notice">ระบบตรวจอีเมลและเบอร์โทรซ้ำทั้งในแอปและ PostgreSQL</div></div>`}
function lookupPage(){const mine=db.bookings.filter(b=>b.email.toLowerCase()===currentUser.email&&b.phone===currentUser.phone).reverse();return `${title('YOUR TICKETS','ตั๋วของฉัน',`${esc(currentUser.firstName)} · ${esc(currentUser.email)}`,`<button class="button secondary small" data-action="logout">ออกจากระบบ</button>`)}<div class="panel lookup-panel"><h2>ค้นหาการจอง</h2><p class="small muted">ค้นหาจากเลขการจองในบัญชีนี้</p><form id="lookup-form"><div class="field"><label for="booking-id">เลขการจอง</label><input id="booking-id" name="bookingId" placeholder="C67-1001" required></div><button class="button full">ค้นหาตั๋ว →</button><p id="lookup-error" class="field-error" role="alert"></p></form></div>${lookupResult?lookupDetails(lookupResult):mine.length?`<div class="panel" style="margin-top:20px"><h3>รายการของบัญชีนี้</h3>${bookingTable(mine)}</div>`:'<div class="empty"><strong>ยังไม่มีการจองในบัญชีนี้</strong><a class="button" href="#home">เลือกภาพยนตร์</a></div>'}`}
function lookupDetails(id){const b=db.bookings.find(x=>x.id===id);if(!b)return '';return `<section id="lookup-details">${ticketMarkup(b)}${couponMarkup(b)}<div class="ticket-actions">${b.status==='paid'?`<button class="button secondary" data-action="download-ticket" data-id="${id}">ดาวน์โหลดตั๋ว ↓</button><button class="button secondary" data-action="request-change" data-id="${id}" ${startTime(b)<=Date.now()?'disabled':''}>ขอเปลี่ยนรอบ</button><button class="button secondary" data-action="confirm-cancel" data-id="${id}" ${startTime(b)<=Date.now()?'disabled':''}>ยกเลิกการจอง</button>`:b.status==='pending'?`<a class="button" href="#payment/${id}">ชำระเงินต่อ</a>`:''}</div>${b.status==='paid'&&startTime(b)<=Date.now()?'<p class="small muted" style="text-align:center">รอบฉายเริ่มแล้ว ไม่สามารถยกเลิกหรือเปลี่ยนรอบได้</p>':''}</section>`}
function cinemasPage(){return `${title('FIND YOUR CINEMA','โรงใกล้คุณ','เลือกสาขาที่สะดวก แล้วไปดูหนังกัน')}<div class="cards-3">${db.cinemas.filter(c=>c.active).map((c,i)=>`<article class="panel"><div class="location-art">${['▤','▥','▦'][i%3]}</div><div class="eyebrow">${esc(c.area)}</div><h3 style="margin-top:12px">${esc(c.name)}</h3><p class="small muted">${esc(c.address)}</p><p class="small muted">เปิด 10:00–22:00 · ${db.rooms.filter(r=>r.cinema===c.id&&r.active).length} ห้องฉาย</p><button class="button secondary full" data-action="cinema-book" data-id="${c.id}">เลือกรอบที่สาขานี้ ↗</button></article>`).join('')}</div><div class="notice">สถานที่ทั้งหมดเป็นข้อมูลสมมติสำหรับโปรเจกต์</div>`}
function promotionsPage(){return `${title('A LITTLE EXTRA','ดูหนังแบบคุ้มกว่า','เลือกโค้ดที่ใช่ แล้วใส่ตอนจอง')}<div class="cards-3">${db.promos.filter(p=>p.active).map(p=>`<article class="promo-card"><span class="pill">สำหรับตั๋วและอาหาร</span><div class="discount">${p.kind==='percent'?p.value+'%':'฿'+p.value}<span style="font-size:17px"> OFF</span></div><h3>${esc(p.name)}</h3><p class="small muted">เมื่อยอดรวมครบ ฿${money(p.min)}</p><button class="code" data-action="copy-code" data-id="${p.id}">${esc(p.code)} ⧉</button></article>`).join('')}</div>`}
function contactPage(){return `${title('WE ARE HERE FOR YOU','มีอะไรให้ช่วยไหม')}<div class="contact-layout"><div class="contact-details"><h2>คุยกับเรา<br>ได้ทุกเรื่องหนัง</h2><p class="muted">สอบถามการจอง หรือแจ้งเรื่องที่อยากให้เราดูแล</p><div class="contact-item"><small>CALL CENTER · ตัวอย่าง</small><strong>02-000-0067</strong></div><div class="contact-item"><small>เวลาทำการ</small><strong>10:00–22:00</strong></div><div class="notice">แบบฟอร์มนี้บันทึกเฉพาะใน Demo<br>ไม่มีการส่งข้อความถึงเจ้าหน้าที่จริง</div></div><div class="panel"><h3>ส่งเรื่องให้เราดูแล</h3><div class="notice" style="margin:16px 0"><strong>ต้องการเปลี่ยนรอบหนัง?</strong><br>กรุณาโทรติดต่อ Call Center 02-000-0067<br><span class="small muted">เวลาทำการ 10:00–22:00 น. · เบอร์โทรตัวอย่างสำหรับ Demo</span></div><form id="complaint-form"><div class="field"><label for="complaint-booking">เลขการจอง (ถ้ามี)</label><input id="complaint-booking" name="booking" placeholder="C67-1001"></div><div class="notice">ผู้แจ้ง: ${esc(currentUser.firstName)} ${esc(currentUser.lastName)}<br>${esc(currentUser.email)} · ${esc(currentUser.phone)}</div><input type="hidden" name="email" value="${esc(currentUser.email)}"><input type="hidden" name="phone" value="${esc(currentUser.phone)}"><div class="field"><label for="complaint-type">ประเภทเรื่อง</label><select id="complaint-type" name="type"><option>การจอง</option><option>การชำระเงิน</option><option>การบริการ</option><option>อื่น ๆ</option></select></div><div class="field"><label for="complaint-detail">รายละเอียด</label><textarea id="complaint-detail" name="detail" placeholder="เล่าให้เราฟังสั้น ๆ" maxlength="1000" required></textarea></div><button class="button full">ส่งเรื่อง →</button></form></div></div>`}
const staffTabs=[['dashboard','ภาพรวม'],['bookings','การจอง'],['movies','ภาพยนตร์'],['rooms','ห้องฉาย / สาขา'],['times','รอบฉาย'],['promos','โปรโมชั่น'],['products','อาหาร / เครื่องดื่ม'],['requests','คำขอเปลี่ยนรอบ'],['complaints','เรื่องร้องเรียน'],['finance','รายงานยอดขาย']];
const roleTabs={'ฝ่ายจัดการ':['dashboard','bookings','movies','rooms','times','promos','products'],'Call Center':['dashboard','bookings','requests'],'การเงิน':['dashboard','finance'],'HR':['dashboard','complaints']};
staffTabs.push(['database','ฐานข้อมูล']);for(const tabs of Object.values(roleTabs))tabs.push('database');let databaseInfo=null;
async function loadDatabaseInfo(){const r=await fetch('/api/database');if(!r.ok)throw new Error('อ่านฐานข้อมูลไม่สำเร็จ');databaseInfo=await r.json();}
function staffPage(){const allowed=roleTabs[staffRole];if(!allowed.includes(staffTab))staffTab=allowed[0];return `${title('STAFF WORKSPACE','หลังบ้าน Cinema67','เลือกบทบาทเพื่อสาธิตระบบฐานข้อมูล',`<div><label for="staff-role" class="small muted">บทบาทจำลอง</label><select id="staff-role">${Object.keys(roleTabs).map(r=>`<option ${r===staffRole?'selected':''}>${r}</option>`).join('')}</select></div>`)}<div class="staff-layout"><aside class="staff-sidebar"><div class="staff-role">${staffRole}<br><span class="pill">DEMO MODE</span></div>${staffTabs.filter(([id])=>allowed.includes(id)).map(([id,name])=>`<button data-action="staff-tab" data-id="${id}" class="${staffTab===id?'active':''}">${name}</button>`).join('')}</aside><section id="staff-content">${staffContent()}</section></div>`}
function bookingTable(list,actions=true){return table(['การจอง','รอบ / ที่นั่ง','สถานะ','ยอดสุทธิ',...(actions?['']:[])],list.map(b=>`<tr><td><div class="table-name">${b.id}<small>${esc(movie(b.movie)?.name)}</small></div></td><td>${dateLabel(b.date)} · ${b.time}<br><span class="muted">${b.seats.join(', ')}</span></td><td>${badge(b.status)}</td><td>฿${money(b.amount)}</td>${actions?`<td><button class="button secondary small" data-action="view-booking" data-id="${b.id}">รายละเอียด</button></td>`:''}</tr>`).join(''))}
function table(headers,body){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${body||`<tr><td colspan="${headers.length}" class="muted">ยังไม่มีรายการ</td></tr>`}</tbody></table></div>`}
function metrics(){const paid=db.bookings.filter(b=>b.status==='paid');return `<div class="metrics"><div class="metric"><p>ยอดขายจำลอง</p><strong>฿${money(paid.reduce((t,b)=>t+b.amount,0))}</strong><small>รายการที่ชำระแล้ว</small></div><div class="metric"><p>การจองทั้งหมด</p><strong>${db.bookings.length}</strong><small>รวมทุกสถานะ</small></div><div class="metric"><p>ตั๋วที่ขายได้</p><strong>${paid.reduce((t,b)=>t+b.seats.length,0)}</strong><small>ที่นั่งที่ชำระแล้ว</small></div><div class="metric"><p>คำร้องรอดำเนินการ</p><strong>${db.requests.filter(x=>x.status==='pending').length+db.complaints.filter(x=>x.status!=='resolved').length}</strong><small>เปลี่ยนรอบ + ร้องเรียน</small></div></div>`}
function staffContent(){let body='';const tab=staffTab;const heading=staffTabs.find(([id])=>id===tab)[1];if(tab==='dashboard'){const paid=db.bookings.filter(b=>b.status==='paid');const max=Math.max(1,...db.movies.map(m=>paid.filter(b=>b.movie===m.id).reduce((t,b)=>t+b.seats.length,0)));return `${metrics()}<div class="staff-dashboard-grid"><div class="panel"><h3>หนังยอดนิยม</h3><p class="small muted">จำนวนที่นั่งที่ชำระแล้ว</p><div class="bar-chart">${db.movies.filter(m=>!m.upcoming).map(m=>{const n=paid.filter(b=>b.movie===m.id).reduce((t,b)=>t+b.seats.length,0);return `<div class="chart-row"><span>${esc(m.name)}</span><div class="bar-track"><div class="bar-fill" style="width:${n/max*100}%"></div></div><span>${n} ที่นั่ง</span></div>`}).join('')}</div></div><div class="panel"><h3>นำเสนอได้ครบใน 3 นาที</h3><div class="guide-step"><b>1</b><p>ลองจองตั๋วจากหน้าภาพยนตร์<br><small>เลือกรอบ ที่นั่ง และชำระจำลอง</small></p></div><div class="guide-step"><b>2</b><p>ค้นหาตั๋วและขอเปลี่ยนรอบ<br><small>ใช้เลขการจองกับอีเมล</small></p></div><div class="guide-step"><b>3</b><p>กลับมาดูผลในหลังบ้าน<br><small>ยอดขาย คำขอ และเรื่องร้องเรียน</small></p></div></div></div><div class="panel" style="margin-top:20px"><h3>การจองล่าสุด</h3>${bookingTable(db.bookings.slice().reverse().slice(0,5))}</div>`}
if(tab==='database')return `<div class="panel database-panel"><div class="staff-head"><div><h2>ฐานข้อมูลตาม DDL</h2><p class="small muted">${databaseInfo?databaseInfo.tables.length:17} ตาราง · ข้อมูลอ่านจาก PostgreSQL</p></div><a class="button small" href="/api/ddl" download>ดาวน์โหลด DDL ↓</a></div>${databaseInfo?table(['ตาราง','จำนวนแถว','คอลัมน์',''],databaseInfo.tables.map(t=>`<tr><td class="table-name">${esc(t.name)}</td><td>${t.count.toLocaleString('th-TH')}</td><td class="small muted">${t.columns.map(c=>esc(c.column_name.toUpperCase())).join(' · ')}</td><td><button class="button secondary small" data-action="database-rows" data-id="${t.name}">ดูข้อมูล</button></td></tr>`).join('')):'<p>กำลังอ่านตาราง…</p>'}</div>`;
if(tab==='bookings')body=`<div class="field"><label class="sr-only" for="staff-search">ค้นหาการจอง</label><input id="staff-search" placeholder="ค้นหาด้วยเลขจอง / อีเมล / เบอร์โทร"></div><div id="staff-results">${bookingTable(db.bookings.slice().reverse())}</div>`;
if(tab==='movies')body=table(['ภาพยนตร์','ประเภท','ความยาว','สถานะ',''],db.movies.map(m=>`<tr><td class="table-name">${esc(m.name)}<small>${esc(m.thai)}</small></td><td>${esc(m.genre)}</td><td>${m.duration} นาที</td><td><span class="pill ${m.active?'':'grey'}">${m.active?(m.upcoming?'เร็ว ๆ นี้':'กำลังฉาย'):'ปิดใช้งาน'}</span></td><td><button class="button secondary small" data-action="edit-record" data-type="movies" data-id="${m.id}">แก้ไข</button><button class="button secondary small" data-action="toggle-record" data-type="movies" data-id="${m.id}">${m.active?'ปิด':'เปิด'}</button></td></tr>`).join(''));
if(tab==='rooms')body=table(['ห้องฉาย','สาขา','ระบบ','ความจุ','สถานะ',''],db.rooms.map(r=>`<tr><td class="table-name">${esc(r.name)}</td><td>${esc(cinema(r.cinema)?.name)}</td><td>${esc(r.type)}</td><td>48 ที่นั่ง</td><td><span class="pill ${r.active?'':'grey'}">${r.active?'เปิดใช้งาน':'ปิดใช้งาน'}</span></td><td><button class="button secondary small" data-action="edit-record" data-type="rooms" data-id="${r.id}">แก้ไข</button><button class="button secondary small" data-action="toggle-record" data-type="rooms" data-id="${r.id}">${r.active?'ปิดห้อง':'เปิดห้อง'}</button></td></tr>`).join(''))+`<div class="notice">แต่ละห้องมี 48 ที่นั่ง · ไม่ปิดห้องที่มีการจองหรือคำขอรอชำระในอนาคต</div><h3 style="margin-top:24px">สาขา</h3>`+table(['สาขา','ที่ตั้ง',''],db.cinemas.map(c=>`<tr><td class="table-name">${esc(c.name)}</td><td>${esc(c.address)}</td><td><button class="button secondary small" data-action="edit-record" data-type="cinemas" data-id="${c.id}">แก้ไข</button></td></tr>`).join(''));
if(tab==='times')body=`<p class="small muted">รอบมาตรฐานใช้กับหนังที่กำลังฉายและห้องที่เปิดอยู่ · ยกเว้นรายการจองเดิม</p>${table(['เวลา','สถานะ',''],db.times.map(t=>`<tr><td class="table-name">${t} น.</td><td><span class="pill">พร้อมจอง</span></td><td><button class="button secondary small" data-action="remove-time" data-id="${t}">นำออก</button></td></tr>`).join(''))}<form id="time-form" class="inline-input" style="margin-top:20px"><label class="sr-only" for="new-time">เพิ่มรอบฉาย</label><input id="new-time" type="time" name="time" required><button class="button">เพิ่มรอบฉาย</button></form>`;
if(tab==='promos')body=table(['โค้ด','โปรโมชั่น','ส่วนลด','ยอดขั้นต่ำ','สถานะ',''],db.promos.map(p=>`<tr><td class="table-name">${esc(p.code)}</td><td>${esc(p.name)}</td><td>${p.kind==='percent'?p.value+'%':'฿'+money(p.value)}</td><td>฿${money(p.min)}</td><td><span class="pill ${p.active?'':'grey'}">${p.active?'เปิดใช้งาน':'ปิดใช้งาน'}</span></td><td><button class="button secondary small" data-action="edit-record" data-type="promos" data-id="${p.id}">แก้ไข</button><button class="button secondary small" data-action="toggle-record" data-type="promos" data-id="${p.id}">${p.active?'ปิด':'เปิด'}</button></td></tr>`).join(''));
if(tab==='products')body=table(['สินค้า','รายละเอียด','ราคา','สถานะ',''],db.products.map(p=>`<tr><td class="table-name">${p.icon} ${esc(p.name)}</td><td>${esc(p.detail)}</td><td>฿${money(p.price)}</td><td><span class="pill ${p.active?'':'grey'}">${p.active?'พร้อมขาย':'ปิดใช้งาน'}</span></td><td><button class="button secondary small" data-action="edit-record" data-type="products" data-id="${p.id}">แก้ไข</button><button class="button secondary small" data-action="toggle-record" data-type="products" data-id="${p.id}">${p.active?'ปิด':'เปิด'}</button></td></tr>`).join(''));
if(tab==='requests')body=table(['คำขอ','การจอง','รอบใหม่','สถานะ',''],db.requests.slice().reverse().map(r=>`<tr><td class="table-name">${r.id}</td><td>${r.booking}</td><td>${dateLabel(r.date)} · ${r.time}</td><td>${badge(r.status,r.status==='pending'?'รอพิจารณา':null)}</td><td><button class="button secondary small" data-action="view-request" data-id="${r.id}">ตรวจสอบ</button></td></tr>`).join(''));
if(tab==='complaints')body=table(['เลขเคส','ประเภท','อีเมล','สถานะ',''],db.complaints.slice().reverse().map(c=>`<tr><td class="table-name">${c.id}</td><td>${esc(c.type)}</td><td>${esc(c.email)}</td><td>${badge(c.status,c.status==='pending'?'รอดำเนินการ':null)}</td><td><button class="button secondary small" data-action="view-complaint" data-id="${c.id}">ดูเรื่อง</button></td></tr>`).join(''));
if(tab==='finance'){const dates=[...new Set(db.bookings.map(b=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Bangkok',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(b.created))))].sort().reverse();body=`${metrics()}<div class="notice">รายงานตามวันที่ทำรายการ · แสดงเฉพาะยอดที่ชำระแล้วและยังไม่ยกเลิก</div>${table(['วันที่','รายการชำระแล้ว','ตั๋ว','ยอดสุทธิ'],dates.map(d=>{const l=db.bookings.filter(b=>b.status==='paid'&&new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Bangkok',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(b.created))===d);return `<tr><td>${dateLabel(d)}</td><td>${l.length}</td><td>${l.reduce((t,b)=>t+b.seats.length,0)}</td><td class="table-name">฿${money(l.reduce((t,b)=>t+b.amount,0))}</td></tr>`}).join(''))}<div style="margin-top:24px">${bookingTable(db.bookings.filter(b=>b.status==='paid'),false)}</div>`;}
const addType={movies:'movies',rooms:'rooms',promos:'promos',products:'products'}[tab];return `<div class="panel"><div class="staff-head"><h2>${heading}</h2>${addType?`<button class="button small" data-action="add-record" data-type="${addType}">+ เพิ่ม${{movies:'หนัง',rooms:'ห้อง',promos:'โปรโมชั่น',products:'สินค้า'}[tab]}</button>`:tab==='finance'?'<button class="button small" data-action="print-report">พิมพ์รายงาน ↗</button>':''}</div>${body}</div>`;}
function notFound(){return `<div class="empty"><strong>ไม่พบรายการนี้</strong><a class="button" href="#home">กลับหน้าแรก</a></div>`}
function go(path){if(location.hash==='#'+path)render();else location.hash=path;}
function render(){const [route='home',id]=location.hash.slice(1).split('/');let html='';if(['login','register'].includes(route))html=currentUser?lookupPage():authPage(route);else if(['booking','payment','ticket','lookup','contact'].includes(route)&&!currentUser)html=authPage('login');else if(route==='home'||!route)html=home();else if(route==='booking')html=bookingPage();else if(route==='payment')html=paymentPage(id);else if(route==='ticket'){const b=db.bookings.find(b=>b.id===id);html=b?.status==='paid'&&b.email.toLowerCase()===currentUser.email?ticketPage(b):notFound()}else if(route==='lookup')html=lookupPage();else if(route==='cinemas')html=cinemasPage();else if(route==='promotions')html=promotionsPage();else if(route==='contact')html=contactPage();else if(route==='staff')html=staffPage();else html=notFound();$('#app').innerHTML=html;updateHeader();$$('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===route||a.dataset.nav==='home'&&['booking','payment','ticket'].includes(route)));$('#mobile-nav').setAttribute('aria-expanded','false');$('.header nav').classList.remove('open')}
function expireBookings(){return false}
window.addEventListener('hashchange',()=>{if(!ready)return;render();window.scrollTo({top:0,behavior:'instant'})});
setInterval(()=>{const [route,id]=location.hash.slice(1).split('/');const b=db?.bookings.find(x=>x.id===id);if(route==='payment'&&$('#countdown')&&b)$('#countdown').textContent=remaining(b)},1000);
setInterval(async()=>{if(!ready||busy||document.hidden||$('#dialog').open)return;busy=true;try{const old=revision;await loadRemote();if(revision!==old){if(staffTab==='database')await loadDatabaseInfo();render()}}catch{}finally{busy=false}},3000);
document.addEventListener('input',e=>{if(e.target.id==='movie-search'){search=e.target.value;$('#movie-results').innerHTML=movieResults()}if(e.target.id==='staff-search'){const q=e.target.value.toLowerCase();$('#staff-results').innerHTML=bookingTable(db.bookings.filter(b=>`${b.id} ${b.email} ${b.phone}`.toLowerCase().includes(q)).reverse())}});
document.addEventListener('change',e=>{if(e.target.id==='genre-filter'){genre=e.target.value;$('#movie-results').innerHTML=movieResults()}if(e.target.id==='branch'){booking.cinema=e.target.value;booking.room=db.rooms.find(r=>r.cinema===booking.cinema&&r.active&&r.movie===booking.movie).id;booking.time='';booking.seats=[];render()}if(e.target.id==='room'){booking.room=e.target.value;booking.time='';booking.seats=[];render()}if(e.target.id==='staff-role'){staffRole=e.target.value;staffTab='dashboard';render()}});
document.addEventListener('submit',guarded(async e=>{const f=e.target;if(!['auth-form','checkout-form','lookup-form','complaint-form','record-form','change-form','time-form'].includes(f.id))return;e.preventDefault();const data=Object.fromEntries(new FormData(f));if(f.id==='auth-form'){await authRequest(f.dataset.mode,data);const movieId=sessionStorage.getItem('cinema67-return-movie');sessionStorage.removeItem('cinema67-return-movie');if(movieId)beginBooking(movieId);else go('lookup');toast(f.dataset.mode==='register'?'สร้างบัญชีและเข้าสู่ระบบแล้ว':'เข้าสู่ระบบแล้ว');return}if(f.id==='checkout-form'){Object.assign(booking,{firstName:currentUser.firstName,lastName:currentUser.lastName,email:currentUser.email,phone:currentUser.phone});if(startTime(booking)<=Date.now()){toast('รอบนี้เริ่มฉายแล้ว กรุณาเลือกรอบใหม่');booking.step=0;render();return}const taken=reserved();if(booking.seats.some(s=>taken.has(s))){toast('ที่นั่งถูกจองแล้ว กรุณาเลือกใหม่');booking.step=1;booking.seats=booking.seats.filter(s=>!taken.has(s));render();return}updateDiscount();const b={...booking,id:'C67-'+db.nextId++,items:{...booking.items},seats:[...booking.seats],status:'pending',amount:subtotal()-booking.discount,created:Date.now(),deadline:Date.now()+600000,couponUsed:false};db.bookings.push(b);await save();go('payment/'+b.id)}
if(f.id==='lookup-form'){const b=db.bookings.find(b=>b.id.toUpperCase()===data.bookingId.trim().toUpperCase()&&b.email.toLowerCase()===currentUser.email&&b.phone===currentUser.phone);if(!b){lookupResult=null;$('#lookup-error').textContent='ไม่พบการจองนี้ในบัญชีของคุณ';$('#lookup-details')?.remove();return}lookupResult=b.id;render();$('#booking-id').value=b.id;$('#lookup-details').scrollIntoView({behavior:'smooth',block:'start'})}
if(f.id==='complaint-form'){const c={...data,id:'CASE-'+String(db.complaints.length+1).padStart(3,'0'),status:'pending',created:Date.now()};db.complaints.push(c);await save();dialog('รับเรื่องแล้วครับ',`<div class="success-mark">✓</div><p>เลขคำร้อง <strong>${c.id}</strong></p><p class="small muted">สถานะ: รอเจ้าหน้าที่ดำเนินการ<br>ดูเคสได้ในส่วนพนักงาน → HR</p>`,`<div class="dialog-actions"><button class="button" data-action="close-dialog">เรียบร้อย</button></div>`);f.reset()}
if(f.id==='record-form')await saveRecord(data,f.dataset.type,f.dataset.id);
if(f.id==='change-form'){const b=db.bookings.find(b=>b.id===f.dataset.id);const next={...b,date:data.date,time:data.time};if(b.status!=='paid'||startTime(b)<=Date.now()||startTime(next)<=Date.now()){toast('ต้องเลือกรอบใหม่ที่ยังไม่เริ่มฉาย');return}if(db.requests.some(r=>r.booking===b.id&&r.status==='pending')){toast('รายการนี้มีคำขอรอพิจารณาอยู่แล้ว');return}const available=48-reserved(next,b.id).size;if(available<b.seats.length){toast('ที่นั่งในรอบใหม่ไม่เพียงพอ');return}db.requests.push({id:'REQ-'+String(db.requests.length+1).padStart(3,'0'),booking:b.id,date:data.date,time:data.time,reason:data.reason,status:'pending',created:Date.now()});await save();closeDialog();toast('ส่งคำขอแล้ว ดูได้ในส่วน Call Center')}
if(f.id==='time-form'){if(db.times.includes(data.time)){toast('มีรอบนี้อยู่แล้ว');return}db.times.push(data.time);db.times.sort();await save();render();toast('เพิ่มรอบฉายแล้ว')}}));
document.addEventListener('click',guarded(async e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const {action:a,id,type}=el.dataset;switch(a){
case 'book':beginBooking(id);break;
case 'logout':{await authRequest('logout',{});currentUser=null;lookupResult=null;go('home');toast('ออกจากระบบแล้ว');break}
case 'scroll-movies':$('#movies').scrollIntoView({behavior:'smooth'});break;
case 'movie-tab':movieTab=id;render();$('#movies').scrollIntoView({block:'start'});break;
case 'date':booking.date=id;booking.time='';booking.seats=[];render();break;
case 'time':booking.time=id;booking.seats=[];render();break;
case 'seat':booking.seats=booking.seats.includes(id)?booking.seats.filter(s=>s!==id):[...booking.seats,id].sort();render();break;
case 'next':if(booking.step===0&&!booking.time||booking.step===1&&!booking.seats.length)return;booking.step=Math.min(3,booking.step+1);render();window.scrollTo({top:0,behavior:'smooth'});break;
case 'previous':booking.step=Math.max(0,booking.step-1);render();break;
case 'leave-booking':go('home');break;
case 'quantity':booking.items[id]=Math.max(0,Math.min(20,(booking.items[id]||0)+Number(el.dataset.delta)));render();break;
case 'apply-promo':{const code=$('#promo').value.trim().toUpperCase();const pr=db.promos.find(p=>p.active&&p.code===code);booking.promo=code;updateDiscount();$('#promo-message').textContent=!pr?'ไม่พบโค้ดนี้ หรือโค้ดปิดใช้งาน':subtotal()<pr.min?`ยอดขั้นต่ำ ฿${money(pr.min)} สำหรับโค้ดนี้`:`ใช้โค้ดแล้ว ลด ฿${money(booking.discount)}`;$('.summary').outerHTML=summary();break}
case 'pay-success':{const b=db.bookings.find(b=>b.id===id);expireBookings();if(b?.status!=='pending'){render();return}if(b.seats.some(s=>reserved(b,b.id).has(s))){toast('ที่นั่งไม่ว่างแล้ว ระบบยกเลิกรายการ');b.status='cancelled';await save();render();return}b.status='paid';await save();go('ticket/'+id);break}
case 'pay-fail':$('#pay-error').textContent='ชำระไม่สำเร็จ ลองใหม่ได้ภายในเวลาที่เหลือ';break;
case 'pay-expire':{const b=db.bookings.find(b=>b.id===id);if(b.status==='pending'){b.deadline=Date.now()-1;b.status='expired';await save();render()}break}
case 'cancel-pending':{const b=db.bookings.find(b=>b.id===id);if(b?.status==='pending'){b.status='cancelled';await save();render()}break}
case 'confirm-cancel':{const b=db.bookings.find(b=>b.id===id);if(!b||b.status!=='paid'||startTime(b)<=Date.now()){toast('รายการนี้ยกเลิกไม่ได้');return}dialog('ยกเลิกการจองนี้?',`<p>${b.id} · ${esc(movie(b.movie).name)}</p><div class="notice">ยกเลิกก่อนเวลาเริ่มฉายเท่านั้น<br>ที่นั่งจะกลับมาว่าง และตั๋ว/คูปองจะใช้งานไม่ได้</div><p class="small muted">Demo นี้จำลองการยกเลิกเท่านั้น ไม่ดำเนินการคืนเงิน</p>`,`<div class="dialog-actions"><button class="button secondary" data-action="close-dialog">เก็บการจองไว้</button><button class="button danger" data-action="cancel-paid" data-id="${id}">ยืนยันยกเลิก</button></div>`);break}
case 'cancel-paid':{const b=db.bookings.find(b=>b.id===id);if(b.status!=='paid'||startTime(b)<=Date.now()){toast('ไม่สามารถยกเลิกรายการได้');closeDialog();return}b.status='cancelled';db.requests.filter(r=>r.booking===id&&r.status==='pending').forEach(r=>r.status='rejected');await save();closeDialog();render();toast('ยกเลิกแล้ว และคืนที่นั่งเรียบร้อย');break}
case 'request-change':changeDialog(id);break;
case 'download-ticket':downloadTicket(id);break;
case 'email-preview':{const b=db.bookings.find(b=>b.id===id);dialog('ตัวอย่างอีเมลยืนยัน',`<p class="small muted">ถึง ${esc(b.email)} · ตัวอย่างเท่านั้น</p><div class="panel"><h3>การจองของคุณสำเร็จแล้ว 🎬</h3><p>${esc(movie(b.movie).name)}</p><p class="small">${dateLabel(b.date)} · ${b.time} น.<br>${esc(cinema(b.cinema).name)}<br>ที่นั่ง ${b.seats.join(', ')}<br>เลขการจอง <strong>${b.id}</strong></p><p class="small muted">แล้วพบกันที่ Cinema67</p></div>`);break}
case 'cinema-book':beginBooking(db.movies.find(m=>m.active&&!m.upcoming).id);booking.cinema=id;booking.room=db.rooms.find(r=>r.cinema===id&&r.active&&r.movie===booking.movie)?.id;if(!booking.room){toast('สาขานี้ยังไม่มีห้องเปิดใช้งาน');go('cinemas')}else render();break;
case 'copy-code':{const pr=db.promos.find(p=>p.id===id);if(navigator.clipboard)navigator.clipboard.writeText(pr.code).then(()=>toast('คัดลอก '+pr.code+' แล้ว')).catch(()=>toast('ใช้โค้ด '+pr.code+' ในขั้นตอนจอง'));else toast('ใช้โค้ด '+pr.code+' ในขั้นตอนจอง');break}
case 'database-rows':{const r=await fetch('/api/database?table='+encodeURIComponent(id));if(!r.ok)throw new Error('อ่านตารางไม่ได้');const value=await r.json(),columns=value.rows.length?Object.keys(value.rows[0]):[];dialog(value.name,columns.length?table(columns.map(x=>esc(x.toUpperCase())),value.rows.map(row=>'<tr>'+columns.map(c=>'<td class="small">'+esc(row[c]??'—')+'</td>').join('')+'</tr>').join('')):'<p>ยังไม่มีข้อมูล</p>','<p class="small muted">ข้อมูลจริงจาก PostgreSQL · แสดงสูงสุด 25 แถว</p>');break}
case 'staff-tab':staffTab=id;if(id==='database')await loadDatabaseInfo();render();break;
case 'view-booking':{const b=db.bookings.find(b=>b.id===id);dialog('รายละเอียด '+id,`<h3>${esc(movie(b.movie)?.name)}</h3><p class="small">${esc(b.email)} · ${esc(b.phone)}<br>${dateLabel(b.date)} · ${b.time} น.<br>${esc(cinema(b.cinema)?.name)} · ${esc(room(b.room)?.name)}<br>ที่นั่ง ${b.seats.join(', ')} · ฿${money(b.amount)}</p>${badge(b.status)}${couponMarkup(b)}`,b.status==='paid'&&Object.values(b.items).some(q=>q>0)&&!b.couponUsed?`<div class="dialog-actions"><button class="button" data-action="redeem-coupon" data-id="${id}">จำลองรับอาหารแล้ว</button></div>`:'');break}
case 'redeem-coupon':{const b=db.bookings.find(b=>b.id===id);if(b.status==='paid'&&!b.couponUsed){b.couponUsed=true;await save();closeDialog();toast('บันทึกการใช้คูปองแล้ว')}break}
case 'add-record':recordDialog(type);break;
case 'edit-record':recordDialog(type,id);break;
case 'toggle-record':await toggleRecord(type,id);break;
case 'remove-time':if(db.bookings.some(b=>b.time===id&&['paid','pending'].includes(b.status)&&startTime(b)>Date.now())){toast('รอบนี้มีการจองอยู่ จึงนำออกไม่ได้');return}if(db.times.length===1){toast('ต้องเหลืออย่างน้อย 1 รอบฉาย');return}db.times=db.times.filter(t=>t!==id);await save();render();toast('นำรอบฉายออกแล้ว');break;
case 'view-request':viewRequest(id);break;
case 'approve-request':await approveRequest(id);break;
case 'reject-request':{const r=db.requests.find(r=>r.id===id);if(r.status==='pending'){r.status='rejected';await save();closeDialog();render();toast('ไม่อนุมัติคำขอแล้ว')}break}
case 'view-complaint':{const c=db.complaints.find(c=>c.id===id);dialog(c.id+' · '+esc(c.type),`<p class="small muted">${esc(c.email)} · ${esc(c.phone)}<br>เลขการจอง: ${esc(c.booking||'—')}</p><div class="notice">${esc(c.detail)}</div>${badge(c.status,c.status==='pending'?'รอดำเนินการ':null)}`,c.status!=='resolved'?`<div class="dialog-actions">${c.status==='pending'?`<button class="button secondary" data-action="complaint-working" data-id="${id}">รับเรื่อง</button>`:''}<button class="button" data-action="complaint-resolve" data-id="${id}">ปิดเคส</button></div>`:'');break}
case 'complaint-working':case 'complaint-resolve':{db.complaints.find(c=>c.id===id).status=a==='complaint-working'?'working':'resolved';await save();closeDialog();render();toast(a==='complaint-working'?'รับเรื่องแล้ว':'ปิดเคสแล้ว');break}
case 'print-report':window.print();break;
case 'close-dialog':closeDialog();break;
case 'reset-demo':{const r=await fetch('/api/reset',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({revision})});const value=await r.json();if(!r.ok)throw new Error(value.error);accept(value);}lookupResult=null;movieTab='now';search='';genre='';closeDialog();go('home');toast('เริ่ม Demo ใหม่แล้ว');break;
}}));
function changeDialog(id){const b=db.bookings.find(b=>b.id===id);if(b.status!=='paid'||startTime(b)<=Date.now()){toast('รายการนี้เปลี่ยนรอบไม่ได้');return}dialog('ขอเปลี่ยนรอบฉาย',`<p class="small muted">${b.id} · รอบเดิม ${dateLabel(b.date)} ${b.time}</p><form id="change-form" data-id="${id}"><div class="form-grid"><div class="field"><label for="change-date">วันที่ใหม่</label><input id="change-date" type="date" name="date" min="${nowDate()}" max="${plusDate(30)}" value="${plusDate(2)}" required></div><div class="field"><label for="change-time">รอบใหม่</label><select id="change-time" name="time">${db.times.map(t=>`<option>${t}</option>`).join('')}</select></div></div><div class="field"><label for="change-reason">เหตุผล</label><textarea id="change-reason" name="reason" maxlength="500" required placeholder="เช่น ต้องการเปลี่ยนเวลาเดินทาง"></textarea></div><div class="notice">เจ้าหน้าที่ Call Center จะตรวจสอบที่นั่งในรอบใหม่<br>คำขอไม่เปลี่ยนตั๋วทันที และไม่มีส่วนต่างราคาใน Demo</div><div class="dialog-actions"><button class="button" type="submit">ส่งคำขอ →</button></div></form>`)}
function viewRequest(id){const r=db.requests.find(r=>r.id===id),b=db.bookings.find(b=>b.id===r.booking);dialog('ตรวจคำขอ '+id,`<h3>${esc(movie(b.movie).name)}</h3><p class="small muted">${b.id} · ${b.seats.length} ที่นั่ง</p><div class="form-grid"><div class="notice"><b>รอบเดิม</b><br>${dateLabel(b.date)}<br>${b.time} น. · ${b.seats.join(', ')}</div><div class="notice orange"><b>รอบใหม่</b><br>${dateLabel(r.date)}<br>${r.time} น.</div></div><p class="small">${esc(r.reason)}</p>${badge(r.status,r.status==='pending'?'รอพิจารณา':null)}`,r.status==='pending'?`<div class="dialog-actions"><button class="button secondary" data-action="reject-request" data-id="${id}">ไม่อนุมัติ</button><button class="button" data-action="approve-request" data-id="${id}">อนุมัติเปลี่ยนรอบ</button></div>`:'')}
async function approveRequest(id){const r=db.requests.find(r=>r.id===id),b=db.bookings.find(b=>b.id===r.booking);if(r.status!=='pending')return;const next={...b,date:r.date,time:r.time};if(b.status!=='paid'||startTime(b)<=Date.now()||startTime(next)<=Date.now()){toast('ไม่สามารถเปลี่ยนรอบที่เริ่มแล้วหรือรายการยกเลิก');return}if(!room(b.room)?.active||!db.times.includes(r.time)){toast('ห้องหรือรอบใหม่ไม่เปิดใช้งาน');return}const taken=reserved(next,b.id);let seats=[...b.seats];if(seats.some(s=>taken.has(s))){const used=new Set();seats=b.seats.map(old=>{const found=rows.flatMap(r=>Array.from({length:8},(_,i)=>r+(i+1))).find(s=>price(s)===price(old)&&!taken.has(s)&&!used.has(s));if(found)used.add(found);return found});if(seats.some(s=>!s)){toast('ที่นั่งโซนเดิมในรอบใหม่ไม่เพียงพอ');return}}b.date=r.date;b.time=r.time;b.seats=seats;r.status='approved';await save();closeDialog();render();toast('เปลี่ยนรอบและอัปเดตตั๋วแล้ว')}
function recordDialog(type,id){const r=id?db[type].find(r=>r.id===id):{};const labels={movies:'ภาพยนตร์',rooms:'ห้องฉาย',promos:'โปรโมชั่น',products:'สินค้า',cinemas:'สาขา'};const field=(name,label,value='',kind='text',extra='')=>`<div class="field"><label for="record-${name}">${label}</label><input id="record-${name}" name="${name}" type="${kind}" value="${esc(value)}" ${extra} required></div>`;let body='';if(type==='movies')body=field('name','ชื่อภาพยนตร์',r.name||'')+field('thai','ชื่อภาษาไทย',r.thai||'')+`<div class="form-grid">${field('genre','ประเภท',r.genre||'ผจญภัย')}${field('duration','ความยาว (นาที)',r.duration||120,'number','min="1" max="400"')}</div>`+field('description','เรื่องย่อ',r.description||'')+`<div class="field"><label for="record-status">สถานะ</label><select name="upcoming" id="record-status"><option value="false" ${!r.upcoming?'selected':''}>กำลังฉาย</option><option value="true" ${r.upcoming?'selected':''}>เร็ว ๆ นี้</option></select></div>`;
if(type==='promos')body=field('code','โค้ดส่วนลด',r.code||'')+field('name','ชื่อโปรโมชั่น',r.name||'')+`<div class="form-grid"><div class="field"><label for="record-kind">ประเภทส่วนลด</label><select id="record-kind" name="kind"><option value="percent" ${r.kind!=='amount'?'selected':''}>เปอร์เซ็นต์</option><option value="amount" ${r.kind==='amount'?'selected':''}>จำนวนเงิน</option></select></div>${field('value','ส่วนลด',r.value||10,'number','min="1" max="10000"')}</div>`+field('min','ยอดขั้นต่ำ (บาท)',r.min??300,'number','min="0" max="100000"');
if(type==='products')body=field('name','ชื่อสินค้า',r.name||'')+field('detail','รายละเอียด',r.detail||'ขนาด M')+field('price','ราคา (บาท)',r.price||99,'number','min="1" max="10000"');
if(type==='rooms')body=field('name','ชื่อห้องฉาย',r.name||'')+`<div class="form-grid"><div class="field"><label for="record-cinema">สาขา</label><select id="record-cinema" name="cinema">${db.cinemas.map(c=>`<option value="${c.id}" ${r.cinema===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label for="record-type">ระบบฉาย</label><select id="record-type" name="type"><option ${r.type==='2D'?'selected':''}>2D</option><option ${r.type==='IMAX'?'selected':''}>IMAX</option></select></div></div><div class="field"><label for="record-movie">หนังประจำห้องสำหรับ Demo</label><select id="record-movie" name="movie">${db.movies.filter(m=>m.active&&!m.upcoming).map(m=>`<option value="${m.id}" ${r.movie===m.id?'selected':''}>${esc(m.name)}</option>`).join('')}</select></div><div class="notice">ผังห้องตัวอย่างมี 48 ที่นั่ง · 6 แถว × 8 ที่นั่ง</div>`;
if(type==='cinemas')body=field('name','ชื่อสาขา',r.name||'')+field('area','พื้นที่',r.area||'')+field('address','ที่อยู่',r.address||'');dialog((id?'แก้ไข':'เพิ่ม')+labels[type],`<form id="record-form" data-type="${type}" data-id="${id||''}">${body}<p class="field-error" id="record-error" role="alert"></p><div class="dialog-actions"><button class="button">บันทึก</button></div></form>`)}
async function saveRecord(data,type,id){const numeric={movies:['duration'],promos:['value','min'],products:['price'],rooms:[],cinemas:[]};for(const k of numeric[type])data[k]=Number(data[k]);for(const k in data)if(typeof data[k]==='string')data[k]=data[k].trim();if(Object.values(data).some(v=>v==='')){$('#record-error').textContent='กรุณากรอกข้อมูลให้ครบ';return}if(type==='promos'){data.code=data.code.toUpperCase();if(data.kind==='percent'&&data.value>100){$('#record-error').textContent='ส่วนลดเปอร์เซ็นต์ต้องไม่เกิน 100';return}if(db.promos.some(p=>p.id!==id&&p.code===data.code)){$('#record-error').textContent='มีโค้ดนี้อยู่แล้ว';return}}
if(type==='rooms'&&id){const old=room(id);if((old.cinema!==data.cinema||old.movie!==data.movie)&&db.bookings.some(b=>b.room===id&&['paid','pending'].includes(b.status)&&startTime(b)>Date.now())){$('#record-error').textContent='ห้องมีการจองอยู่ จึงเปลี่ยนสาขาไม่ได้';return}}
if(type==='movies')data.upcoming=data.upcoming==='true';if(id)Object.assign(db[type].find(r=>r.id===id),data);else{if(type==='rooms')data.movie=data.movie||'m1';const prefix={movies:'m',rooms:'r',promos:'pr',products:'p',cinemas:'c'}[type];db[type].push({id:prefix+Date.now().toString(36),active:true,...(type==='movies'?{rating:'ทั่วไป',language:'เสียงไทย',type:'2D',art:'horizon'}:type==='products'?{icon:'🍿'}:{}),...data})}await save();closeDialog();render();toast('บันทึกแล้ว')}
async function toggleRecord(type,id){const r=db[type].find(r=>r.id===id);if(type==='rooms'&&r.active&&db.bookings.some(b=>b.room===id&&['paid','pending'].includes(b.status)&&startTime(b)>Date.now())){toast('ห้องนี้มีการจองในอนาคต จึงปิดไม่ได้');return}if(type==='movies'&&r.active&&db.bookings.some(b=>b.movie===id&&['paid','pending'].includes(b.status)&&startTime(b)>Date.now())){toast('หนังนี้มีการจองในอนาคต จึงปิดไม่ได้');return}r.active=!r.active;await save();render();toast(r.active?'เปิดใช้งานแล้ว':'ปิดใช้งานแล้ว')}
function downloadTicket(id){const b=db.bookings.find(b=>b.id===id);if(!b||b.status!=='paid'){toast('ตั๋วนี้ใช้งานไม่ได้');return}const m=movie(b.movie);const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="900" height="470" viewBox="0 0 900 470"><rect width="900" height="470" rx="24" fill="#f7f7f2"/><rect width="900" height="95" rx="24" fill="#18251f"/><text x="40" y="60" fill="white" font-family="Arial" font-size="30">CINEMA67 / E-TICKET</text><g fill="#202722" font-family="Arial,sans-serif"><text x="40" y="155" font-size="29">${esc(m.name)}</text><text x="40" y="205" font-size="20">${esc(cinema(b.cinema).name)} · ${esc(room(b.room).name)}</text><text x="40" y="250" font-size="22">${b.date} / ${b.time}</text><text x="40" y="300" font-size="22">SEATS: ${b.seats.join(', ')}</text><text x="40" y="345" font-size="20">THB ${b.amount} · ${b.id}</text><text x="40" y="402" font-size="15">${esc(b.email)}</text><text x="40" y="442" font-size="13" fill="#7a807a">PROJECT DEMO ONLY — NOT A VALID CINEMA TICKET</text></g><svg x="630" y="140" width="220" height="220" viewBox="-2 -2 29 29">${qr(b.id).replace(/^<svg[^>]*>/,'').replace(/<\/svg>$/,'')}</svg></svg>`;const url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=id+'-ticket.svg';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('ดาวน์โหลดตั๋วแล้ว')}
$('#mobile-nav').addEventListener('click',()=>{const open=$('.header nav').classList.toggle('open');$('#mobile-nav').setAttribute('aria-expanded',String(open))});
$('#guide-open').addEventListener('click',()=>dialog('ขั้นตอน Demo สำหรับนำเสนอ',`<div class="notice">ก่อนเริ่ม: เปิดผังที่นั่งและหลังบ้าน → ฐานข้อมูล เพื่อแสดงสถานะเริ่มต้น</div><div class="guide-step"><b>1</b><p>เลือก Dune: Part Two<br><small>เลือกรอบวันพรุ่งนี้ เลือก 2 ที่นั่ง แล้วเพิ่ม Movie Combo</small></p></div><div class="guide-step"><b>2</b><p>กรอกข้อมูลและลองโค้ด MOVIE10<br><small>กดชำระสำเร็จ เพื่อรับตั๋วและดาวน์โหลด</small></p></div><div class="guide-step"><b>3</b><p>ค้นหาตั๋ว แล้วลองเปลี่ยนรอบ<br><small>ใช้ C67-1001 กับ demo@example.com ได้ทันที</small></p></div><div class="guide-step"><b>4</b><p>เปิดส่วนพนักงานเพื่อดูผล<br><small>เปิด CUSTOMER_ORDER, TICKET, SHOWTIME_SEAT, PAYMENT เพื่อดูผลจริง แล้วดู BOOKING_OPERATION</small></p></div><div class="guide-step"><b>5</b><p>ลองกรณีที่ระบบต้องปฏิเสธ<br><small>กดเลือกที่นั่งที่จองแล้ว หรือจำลองหมดเวลา แล้วตรวจว่าระบบไม่ยอมชำระ</small></p></div><div class="notice">ข้อมูลจำลองเก็บใน PostgreSQL ร่วมกันทุกเครื่อง · กด “เริ่ม Demo ใหม่” เพื่อคืนข้อมูลตัวอย่าง</div>`));
$('#reset-open').addEventListener('click',()=>dialog('เริ่ม Demo ใหม่?',`<p class="muted">คืนข้อมูลตัวอย่างทั้งหมดในฐานข้อมูลร่วม ทุกเครื่องจะเห็นข้อมูลใหม่</p>`,`<div class="dialog-actions"><button class="button secondary" data-action="close-dialog">กลับ</button><button class="button" data-action="reset-demo">เริ่มใหม่</button></div>`));
$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const rect=$('#dialog').getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)closeDialog()}});
$('#app').innerHTML='<div class="empty"><strong>กำลังโหลด Cinema67…</strong></div>';
loadRemote().then(()=>{ready=true;render()}).catch(()=>{$('#app').innerHTML='<div class="empty"><strong>ยังเชื่อมฐานข้อมูลไม่ได้</strong><p>กรุณาลองโหลดหน้าใหม่อีกครั้ง</p><button class="button" onclick="location.reload()">ลองอีกครั้ง</button></div>'});

